schemaSql:
-- Enable RLS on all created tables
-- Schema setup for DMC (Diala Medical & Chemical Equipment)

-- 1. Settings Table (Stores Daily USD Exchange Rate and App Config)
create table if not exists public.tarag3_settings (
  id bigint primary key generated always as identity,
  usd_rate numeric(12, 2) not null default 1100.00,
  store_name text not null default 'DMC Diala Medical & Chemical Equipment',
  store_phone text default '0912345678',
  store_whatsapp text default '249912345678',
  store_address text default 'عطبرة - شارع الدكاترة',
  updated_at timestamptz default now()
);

alter table public.tarag3_settings enable row level security;

drop policy if exists "Settings are viewable by authenticated users" on public.tarag3_settings;
create policy "Settings are viewable by authenticated users"
  on public.tarag3_settings for select
  to authenticated
  using (true);

drop policy if exists "Settings are editable by admins only" on public.tarag3_settings;
create policy "Settings are editable by admins only"
  on public.tarag3_settings for all
  to authenticated
  using (public.tarag3_is_admin())
  with check (public.tarag3_is_admin());

-- Insert default setting if empty
insert into public.tarag3_settings (usd_rate)
select 1100.00
where not exists (select 1 from public.tarag3_settings);

-- 2. Delivery Areas Table
create table if not exists public.tarag3_delivery_areas (
  id bigint primary key generated always as identity,
  name text not null unique,
  delivery_fee numeric(12, 2) not null default 0.00,
  created_at timestamptz default now()
);

alter table public.tarag3_delivery_areas enable row level security;

drop policy if exists "Delivery areas viewable by authenticated" on public.tarag3_delivery_areas;
create policy "Delivery areas viewable by authenticated"
  on public.tarag3_delivery_areas for select
  to authenticated
  using (true);

drop policy if exists "Delivery areas manageable by admin" on public.tarag3_delivery_areas;
create policy "Delivery areas manageable by admin"
  on public.tarag3_delivery_areas for all
  to authenticated
  using (public.tarag3_is_admin())
  with check (public.tarag3_is_admin());

-- Insert sample delivery areas
insert into public.tarag3_delivery_areas (name, delivery_fee) values
  ('عطبرة', 3000.00),
  ('الدامر', 2500.00),
  ('بربر', 4000.00),
  ('أبوحمد', 6000.00)
on conflict (name) do update set delivery_fee = excluded.delivery_fee;

-- 3. Products Table
create table if not exists public.tarag3_products (
  id bigint primary key generated always as identity,
  name text not null,
  category text not null check (category in ('معدات', 'مستهلكات', 'مختبر')),
  description text,
  price_usd numeric(12, 2) not null default 0.00,
  stock_quantity integer not null default 0,
  image_url text,
  is_visible boolean not null default true,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

alter table public.tarag3_products enable row level security;

drop policy if exists "Products viewable by authenticated" on public.tarag3_products;
create policy "Products viewable by authenticated"
  on public.tarag3_products for select
  to authenticated
  using (is_visible = true or public.tarag3_is_admin());

drop policy if exists "Products manageable by admin" on public.tarag3_products;
create policy "Products manageable by admin"
  on public.tarag3_products for all
  to authenticated
  using (public.tarag3_is_admin())
  with check (public.tarag3_is_admin());

-- Insert sample products
insert into public.tarag3_products (name, category, description, price_usd, stock_quantity, is_visible)
select 'محلول جلوكوز Glucose 5% 500ml', 'مختبر', 'محلول جلوكوز ورايدي معقم 5% سعة 500 مل للاستخدام الطبي والمختبري', 50.00, 120, true
where not exists (select 1 from public.tarag3_products where name = 'محلول جلوكوز Glucose 5% 500ml');

insert into public.tarag3_products (name, category, description, price_usd, stock_quantity, is_visible)
select 'جهاز قياس ضغط الدم الرقمي', 'معدات', 'جهاز قياس ضغط إلكتروني عالي الدقة مع شاشة رقمية وسوار مريح', 180.00, 15, true
where not exists (select 1 from public.tarag3_products where name = 'جهاز قياس ضغط الدم الرقمي');

insert into public.tarag3_products (name, category, description, price_usd, stock_quantity, is_visible)
select 'شاش طبي معقم 10×10 سم (علبة)', 'مستهلكات', 'علبة شاش معقم قطني عالي الإمتصاص للاستخدام الميداني والجراحي', 15.00, 300, true
where not exists (select 1 from public.tarag3_products where name = 'شاش طبي معقم 10×10 سم (علبة)');

insert into public.tarag3_products (name, category, description, price_usd, stock_quantity, is_visible)
select 'حقن سرنجات 5مل معقمة (100 قطعة)', 'مستهلكات', 'علبة حقن معقمة للاستخدام المرة الواحدة سعة 5 مل', 30.00, 0, false
where not exists (select 1 from public.tarag3_products where name = 'حقن سرنجات 5مل معقمة (100 قطعة)');

-- 4. Cart Items Table
create table if not exists public.tarag3_cart_items (
  id bigint primary key generated always as identity,
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  product_id bigint not null references public.tarag3_products(id) on delete cascade,
  quantity integer not null default 1 check (quantity > 0),
  created_at timestamptz default now(),
  unique(customer_id, product_id)
);

alter table public.tarag3_cart_items enable row level security;

drop policy if exists "Customers manage their cart" on public.tarag3_cart_items;
create policy "Customers manage their cart"
  on public.tarag3_cart_items for all
  to authenticated
  using (customer_id = auth.uid() or public.tarag3_is_admin())
  with check (customer_id = auth.uid() or public.tarag3_is_admin());

-- 5. Orders Table
create table if not exists public.tarag3_orders (
  id bigint primary key generated always as identity,
  order_number text not null unique,
  customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  customer_name text not null,
  customer_phone text not null,
  delivery_area_id bigint references public.tarag3_delivery_areas(id) on delete set null,
  delivery_area_name text not null,
  delivery_address text,
  delivery_type text not null check (delivery_type in ('delivery', 'pickup')),
  payment_method text not null default 'cash_on_delivery',
  status text not null default 'جديد' check (status in ('جديد', 'قيد التجهيز', 'في الطريق', 'تم')),
  subtotal_sdg numeric(12, 2) not null default 0.00,
  delivery_fee numeric(12, 2) not null default 0.00,
  total_sdg numeric(12, 2) not null default 0.00,
  usd_rate_used numeric(12, 2) not null default 1100.00,
  notes text,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

alter table public.tarag3_orders enable row level security;

drop policy if exists "Customers can view their orders" on public.tarag3_orders;
create policy "Customers can view their orders"
  on public.tarag3_orders for select
  to authenticated
  using (customer_id = auth.uid() or public.tarag3_is_admin());

drop policy if exists "Customers can create orders" on public.tarag3_orders;
create policy "Customers can create orders"
  on public.tarag3_orders for insert
  to authenticated
  with check (customer_id = auth.uid() or public.tarag3_is_admin());

drop policy if exists "Admins can update orders" on public.tarag3_orders;
create policy "Admins can update orders"
  on public.tarag3_orders for update
  to authenticated
  using (public.tarag3_is_admin() or customer_id = auth.uid())
  with check (public.tarag3_is_admin() or customer_id = auth.uid());

-- 6. Order Items Table
create table if not exists public.tarag3_order_items (
  id bigint primary key generated always as identity,
  order_id bigint not null references public.tarag3_orders(id) on delete cascade,
  product_id bigint references public.tarag3_products(id) on delete set null,
  product_name text not null,
  quantity integer not null check (quantity > 0),
  price_usd numeric(12, 2) not null,
  price_sdg numeric(12, 2) not null,
  total_sdg numeric(12, 2) not null,
  created_at timestamptz default now()
);

alter table public.tarag3_order_items enable row level security;

drop policy if exists "Order items viewable by order owner or admin" on public.tarag3_order_items;
create policy "Order items viewable by order owner or admin"
  on public.tarag3_order_items for select
  to authenticated
  using (
    exists (
      select 1 from public.tarag3_orders
      where id = tarag3_order_items.order_id
        and (customer_id = auth.uid() or public.tarag3_is_admin())
    )
  );

drop policy if exists "Order items insertable by authenticated" on public.tarag3_order_items;
create policy "Order items insertable by authenticated"
  on public.tarag3_order_items for insert
  to authenticated
  with check (
    exists (
      select 1 from public.tarag3_orders
      where id = tarag3_order_items.order_id
        and (customer_id = auth.uid() or public.tarag3_is_admin())
    )
  );

-- 7. Purchases Table (Suppliers & Stock Invoices)
create table if not exists public.tarag3_purchases (
  id bigint primary key generated always as identity,
  supplier_name text not null,
  purchase_date date not null default current_date,
  amount_sdg numeric(12, 2) not null default 0.00,
  payment_status text not null check (payment_status in ('مدفوع', 'آجل')),
  invoice_image_url text,
  notes text,
  created_at timestamptz default now()
);

alter table public.tarag3_purchases enable row level security;

drop policy if exists "Purchases manageable by admin only" on public.tarag3_purchases;
create policy "Purchases manageable by admin only"
  on public.tarag3_purchases for all
  to authenticated
  using (public.tarag3_is_admin())
  with check (public.tarag3_is_admin());

-- Insert sample purchases
insert into public.tarag3_purchases (supplier_name, purchase_date, amount_sdg, payment_status, notes)
select 'شركة الخرطوم للأدوية والمستلزمات', '2024-05-20', 1850000.00, 'مدفوع', 'شحنة محلول جلوكوز وسرنجات'
where not exists (select 1 from public.tarag3_purchases where supplier_name = 'شركة الخرطوم للأدوية والمستلزمات');

insert into public.tarag3_purchases (supplier_name, purchase_date, amount_sdg, payment_status, notes)
select 'مورد المعدات الطبية العالمية', '2024-05-12', 950000.00, 'آجل', 'استيراد أجهزة ضغط وسكر'
where not exists (select 1 from public.tarag3_purchases where supplier_name = 'مورد المعدات الطبية العالمية');

-- 8. Promotions and Offers Log Table
create table if not exists public.tarag3_promotions (
  id bigint primary key generated always as identity,
  title text not null,
  body text not null,
  sent_at timestamptz default now(),
  reached_count integer default 0
);

alter table public.tarag3_promotions enable row level security;

drop policy if exists "Promotions viewable by authenticated" on public.tarag3_promotions;
create policy "Promotions viewable by authenticated"
  on public.tarag3_promotions for select
  to authenticated
  using (true);

drop policy if exists "Promotions manageable by admin" on public.tarag3_promotions;
create policy "Promotions manageable by admin"
  on public.tarag3_promotions for all
  to authenticated
  using (public.tarag3_is_admin())
  with check (public.tarag3_is_admin());

-- Trigger function to handle notifications on order status update or new order
create or replace function public.tarag3_handle_order_notifications()
returns trigger as $$
begin
  if (TG_OP = 'INSERT') then
    -- Notify admins about new incoming order
    insert into public.tarag3_notifications(to_user, to_role, title, body, data)
    values (
      null,
      'admin',
      'طلب جديد #' || NEW.order_number,
      'طلب جديد من ' || NEW.customer_name || ' بقيمة ' || NEW.total_sdg || ' ج.س',
      jsonb_build_object('order_id', NEW.id, 'status', NEW.status)
    );
  elsif (TG_OP = 'UPDATE' and OLD.status <> NEW.status) then
    -- Notify customer about order status change
    insert into public.tarag3_notifications(to_user, to_role, title, body, data)
    values (
      NEW.customer_id,
      'customer',
      'تحديث حالة الطلب #' || NEW.order_number,
      'طلبك الآن في مرحلة (' || NEW.status || ')',
      jsonb_build_object('order_id', NEW.id, 'status', NEW.status)
    );
  end if;
  return NEW;
end;
$$ language plpgsql security definer;

drop trigger if exists tarag3_order_notify_trg on public.tarag3_orders;
create trigger tarag3_order_notify_trg
  after insert or update on public.tarag3_orders
  for each row execute function public.tarag3_handle_order_notifications();
